import re
import urllib.parse
import requests
import json
def task_func(myString, API_KEY):
    if not isinstance(myString, str) or not myString:
        return {}
    if not isinstance(API_KEY, str) or not API_KEY:
        return {}

    url_pattern = r'https?://[^\s\'"]+'
    urls = re.findall(url_pattern, myString)

    domains = set()
    for url in urls:
        parsed = urllib.parse.urlparse(url)
        domain = parsed.netloc.split('@')[-1].split(':')[0]
        if domain:
            domains.add(domain)

    result = {}
    for domain in domains:
        try:
            response = requests.get(
                f"http://ip-api.com/json/{domain}",
                params={"key": API_KEY},
                timeout=10
            )
            if response.status_code == 200:
                try:
                    data = response.json()
                except json.JSONDecodeError:
                    data = None
                result[domain] = data
            else:
                result[domain] = None
        except requests.RequestException:
            result[domain] = None

    return result
