import pandas as pd
import seaborn as sns
import matplotlib.pyplot as plt
HEADERS = {
    'accept': 'application/json'
}
def task_func(url, parameters):
    if not isinstance(url, str) or not url:
        raise Exception("Invalid URL provided.")
    try:
        response = requests.get(url, headers=HEADERS, params=parameters, verify=False)
        response.raise_for_status()
        try:
            data = response.json()
        except ValueError:
            data = json.loads(response.text)
        if not data:
            raise Exception("Empty data received from the API.")
        if isinstance(data, dict):
            if 'data' in data and isinstance(data['data'], list):
                records = data['data']
            else:
                records = [data]
        elif isinstance(data, list):
            records = data
        else:
            raise Exception("Invalid data format received from the API.")
        df = pd.DataFrame(records)
        if df.empty:
            raise Exception("DataFrame is empty after conversion.")
        numeric_df = df.select_dtypes(include='number')
        if numeric_df.empty:
            raise Exception("No numerical data available for correlation.")
        corr = numeric_df.corr()
        fig, ax = plt.subplots()
        sns.heatmap(corr, ax=ax, annot=False, cmap="viridis")
        plt.show()
        return df, ax
    except Exception as e:
        raise Exception(f"Error processing the API data: {e}")
```

